// READ (Fetch items)
const fetchProducts = useCallback(async () => {
  try {
    const res = await axios.get('http://localhost:4000/api/seller/products');
    if (res.data.success) setProducts(res.data.products);
  } catch (err) {
    console.error('Error fetching catalog:', err);
  }
}, []);

// CREATE (Add Item)
const handleAddProductSubmit = async (e) => {
  e.preventDefault();
  try {
    const res = await axios.post('http://localhost:4000/api/seller/products', newProduct);
    if (res.data.success) {
      setIsAddModalOpen(false);
      fetchProducts();
    }
  } catch (err) {
    alert(err.response?.data?.message || 'Create failed');
  }
};

// UPDATE (Edit Price/Stock)
const handleUpdateProductSubmit = async (e) => {
  e.preventDefault();
  try {
    const res = await axios.put(`http://localhost:4000/api/seller/products/${editingProduct._id}`, editingProduct);
    if (res.data.success) {
      setEditingProduct(null);
      fetchProducts();
    }
  } catch (err) {
    alert(err.response?.data?.message || 'Update failed');
  }
};

// DELETE (Remove Item)
const handleDeleteProduct = async (id) => {
  if (window.confirm('Delete this product permanently?')) {
    try {
      const res = await axios.delete(`http://localhost:4000/api/seller/products/${id}`);
      if (res.data.success) fetchProducts();
    } catch (err) {
      alert(err.response?.data?.message || 'Delete failed');
    }
  }
};
